Rules.InvariantScript:
UpdateContext({var_visibleSpinLoader: true});
UpdateContext(
    {
        varTempPass: First(
            SortByColumns(
                Filter(
                    User,
                    Usuarios = txtUser_2.Text
                ),
                "ID",
                SortOrder.Ascending
            )
        ).Senha
    }
);
If(
    LookUp(
        User,
        Usuarios = txtUser_2.Text,
        Senha = Concatenate(
            Left(
                txtSenha_2.Text,
                2
            ),
            Mid(
                varTempPass,
                3,
                110
            ),
            Mid(
                txtSenha_2.Text,
                3,
                2
            ),
            Mid(
                varTempPass,
                115,
                110
            ),
            Mid(
                txtSenha_2.Text,
                5
            )
        )
    ),
    Set(
        varIdUser,
        LookUp(
            User,
            Usuarios = txtUser_2.Text
        ).ID
    );
    Set(
        varNomeUser,
        LookUp(
            User,
            Usuarios = txtUser_2.Text
        ).usrNome
    );
    Set(
        varEmailUser,
        LookUp(
            User,
            Usuarios = txtUser_2.Text
        ).Email
    );
    Set(
        varFuncaoUser,
        LookUp(
            User,
            Usuarios = txtUser_2.Text
        ).Funcao
    );
    Set(
        varBlocoUser,
        LookUp(
            User,
            Usuarios = txtUser_2.Text
        ).Bloco
    );
    Set(
        varAeroUser,
        LookUp(
            User,
            Usuarios = txtUser_2.Text
        ).Aeroporto
    );
    Set(
        varICAOUser,
        LookUp(
            colAeros,
            Aeroporto = varAeroUser
        ).ICAO
    );
    Set(
        varIATAUser,
        LookUp(
            colAeros,
            Aeroporto = varAeroUser
        ).IATA
    );
    Set(
        varPerfilUser,
        LookUp(
            User,
            Usuarios = txtUser_2.Text
        ).Perfil
    );
    Set(
        varAutUser,
        LookUp(
            User,
            Usuarios = txtUser_2.Text
        ).Autorizacao
    );
    // 📄 Carrega inspeções do dia para o aeroporto do usuário
ClearCollect(
        col_inspPista_mob,
        SortByColumns(
            Filter(
                '7.4-tbl_InspPista',
                StartsWith(
                    Aeroporto,
                    varAeroUser
                ) && Data = Today()
            ),
            "ID",
            SortOrder.Descending
        )
    );
    // 🔁 Inicializa coleções temporárias vazias (mantém estrutura)
ClearCollect(
        col_inspPista_mob_temp,
        FirstN(
            col_inspPista_mob,
            0
        )
    );
    ClearCollect(
        col_inspPistaItens_mob_temp,
        FirstN(
            AddColumns(
                '7.4.1-tbl_InspPistaItens',
                InspHash,
                ""
            ),
            0
        )
    );
    // 🚨 Carrega itens não conformes (hoje) por local
Concurrent(
        ClearCollect(
            col_itensPouso,
            Filter(
                '7.4.1-tbl_InspPistaItens',
                Aeroporto = varAeroUser && Local = "Pista de Pouso" && Status = "Não conforme" && Year(Criado) = Year(Today())
            )
        ),
        ClearCollect(
            col_itensTaxi,
            Filter(
                '7.4.1-tbl_InspPistaItens',
                Aeroporto = varAeroUser && Local = "Pista de taxi" && Status = "Não conforme" && Year(Criado) = Year(Today())
            )
        ),
        ClearCollect(
            col_itensAids,
            Filter(
                '7.4.1-tbl_InspPistaItens',
                Aeroporto = varAeroUser && Local = "NAV AIDS" && Status = "Não conforme" && Year(Criado) = Year(Today())
            )
        )
    );
    Set(
        Logado,
        true
    );
    Navigate(
        frmInspPistaMob,
        ScreenTransition.Fade
    ),
    Notify(
        "Usuario ou Senha não conferem",
        NotificationType.Error
    )
)

